-- Table structure for job_applications_v3
-- ----------------------------
DROP TABLE IF EXISTS `job_applications_v3`;
CREATE TABLE `job_applications_v3`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `job_id` bigint NOT NULL,
  `resume_id` bigint NULL DEFAULT NULL,
  `reviewer_agent_score` decimal(5, 2) NULL DEFAULT NULL COMMENT 'AI 筛选分',
  `reviewer_agent_comment` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT 'AI 建议',
  `admin_decision` tinyint NOT NULL DEFAULT 0 COMMENT '0=待处理 1=通过 2=拒绝',
  `admin_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `enterprise_email` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT 1,
  `create_time` bigint NULL DEFAULT NULL,
  `update_time` bigint NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_job`(`job_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of job_applications_v3
-- ----------------------------

-- ----------------------------
-- Table structure for job_positions_v3
-- ----------------------------
DROP TABLE IF EXISTS `job_positions_v3`;
CREATE TABLE `job_positions_v3`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '岗位名称',
  `company` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '公司名称',
  `level` enum('junior','mid','senior') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'junior' COMMENT '岗位级别 §7.4',
  `jd_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '原始 JD 文本',
  `required_skills` json NULL COMMENT '必须技能 [{name,weight}]',
  `preferred_skills` json NULL COMMENT '加分技能 [{name,weight}]',
  `salary_range` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '薪资范围',
  `location` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '工作地点',
  `delivery_threshold` tinyint NOT NULL DEFAULT 60 COMMENT '投递门槛百分比 §7.4',
  `source` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'manual' COMMENT 'manual/jd_parser/enterprise',
  `confidence_score` decimal(3, 2) NULL DEFAULT NULL COMMENT 'JD 解析置信度',
  `enterprise_id` bigint NULL DEFAULT NULL COMMENT '关联企业',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '0=下架 1=上架',
  `neo4j_node_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `create_time` bigint NULL DEFAULT NULL,
  `update_time` bigint NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_level`(`level` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of job_positions_v3
-- ----------------------------

-- ----------------------------
-- Table structure for knowledge_base_v3
-- ----------------------------
DROP TABLE IF EXISTS `knowledge_base_v3`;
CREATE TABLE `knowledge_base_v3`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `skill_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属技能',
  `resource_type` enum('lecture','choice','fill','coding','essay','graph') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` json NOT NULL COMMENT 'Markdown讲义/题目/图谱数据',
  `version` int NOT NULL DEFAULT 1,
  `source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '来源',
  `reviewed_by` bigint NULL DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1=正常 0=待审查 2=已过期',
  `create_time` bigint NULL DEFAULT NULL,
  `update_time` bigint NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_skill`(`skill_name` ASC) USING BTREE,
  INDEX `idx_type`(`resource_type` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of knowledge_base_v3
-- ----------------------------

-- ----------------------------
-- Table structure for evidence_chunks
-- ----------------------------
DROP TABLE IF EXISTS `evidence_chunks`;
CREATE TABLE `evidence_chunks`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '关联用户',
  `source_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证据来源：project/file_qa/evaluation/learning_commit/agent_output/resume',
  `source_id` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源唯一ID，如 project:45 / file_qa:1:1720000000',
  `chunk_index` int NOT NULL DEFAULT 0 COMMENT '第几个分块',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '证据标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原文片段',
  `content_hash` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容哈希，用于去重',
  `skill_tags` json NULL COMMENT '技能标签',
  `job_target_id` bigint NULL DEFAULT NULL COMMENT '关联目标岗位',
  `confidence` decimal(4, 2) NOT NULL DEFAULT 0.70 COMMENT '证据可信度',
  `visibility` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'private' COMMENT 'private=仅本人 school_aggregate=可聚合',
  `vector_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'pending/indexed/failed',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1=正常 0=删除',
  `create_time` bigint NULL DEFAULT NULL COMMENT '创建时间戳ms',
  `update_time` bigint NULL DEFAULT NULL COMMENT '更新时间戳ms',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_source`(`user_id`, `source_type`, `source_id`) USING BTREE,
  INDEX `idx_user_skill`(`user_id`, `skill_tags`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '个人证据索引（Evidence RAG）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for learning_branches_v3
-- ----------------------------
DROP TABLE IF EXISTS `learning_branches_v3`;
CREATE TABLE `learning_branches_v3`  (
  `status` tinyint NOT NULL DEFAULT 1,
  `id` bigint NOT NULL AUTO_INCREMENT,
  `create_time` bigint NULL DEFAULT NULL,
  `update_time` bigint NULL DEFAULT NULL,
  `user_id` bigint NOT NULL,
  `branch_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `branch_type` enum('main','plan','side','experiment') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'main',
  `plan_id` bigint NULL DEFAULT NULL,
  `base_commit_id` bigint NULL DEFAULT NULL,
  `head_commit_id` bigint NULL DEFAULT NULL,
  `source_branch_id` bigint NULL DEFAULT NULL,
  `merged_at` bigint NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_learning_branches_user_status`(`user_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_learning_branches_user_type`(`user_id` ASC, `branch_type` ASC) USING BTREE,
  INDEX `idx_learning_branches_user_plan`(`user_id` ASC, `plan_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

