-- ----------------------------
-- Table structure for learning_commits_v3
-- ----------------------------
DROP TABLE IF EXISTS `learning_commits_v3`;
CREATE TABLE `learning_commits_v3`  (
  `status` tinyint NOT NULL DEFAULT 1,
  `id` bigint NOT NULL AUTO_INCREMENT,
  `create_time` bigint NULL DEFAULT NULL,
  `update_time` bigint NULL DEFAULT NULL,
  `user_id` bigint NOT NULL,
  `branch_id` bigint NOT NULL,
  `parent_commit_id` bigint NULL DEFAULT NULL,
  `merge_source_commit_id` bigint NULL DEFAULT NULL,
  `commit_type` enum('baseline','lecture_read','quiz_passed','quiz_failed','code_done','skill_complete','task_done','manual','merge','rollback') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `skill_name` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `message` varchar(240) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `payload_json` json NULL,
  `snapshot_id` bigint NULL DEFAULT NULL,
  `delta_json` json NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_learning_commits_user_branch`(`user_id` ASC, `branch_id` ASC) USING BTREE,
  INDEX `idx_learning_commits_branch_parent`(`branch_id` ASC, `parent_commit_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

