-- Records of learning_commits_v3
-- ----------------------------

-- ----------------------------
-- Table structure for learning_plans_v3
-- ----------------------------
DROP TABLE IF EXISTS `learning_plans_v3`;
CREATE TABLE `learning_plans_v3`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `plan_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Default Plan' COMMENT '计划名称（中文由应用层写入）',
  `plan_type` enum('main','side') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'main' COMMENT '主线/支线 §4.3',
  `target_job_id` bigint NULL DEFAULT NULL COMMENT '目标岗位',
  `plan_status` enum('active','paused','archived') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `schedule_enabled` tinyint NOT NULL DEFAULT 1,
  `path_data` json NULL COMMENT '阶段→技能点→资源 完整结构',
  `current_phase` int NOT NULL DEFAULT 0 COMMENT '当前阶段索引',
  `daily_hours` decimal(3, 1) NULL DEFAULT NULL COMMENT '本计划每日时长',
  `main_ratio` tinyint NULL DEFAULT 80 COMMENT '主线占比 %',
  `match_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '当前匹配度',
  `estimated_date` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预计达成日期',
  `branch_from` bigint NULL DEFAULT NULL COMMENT '分支来源计划ID（Git模型）§2.3',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1=进行中 2=已完成 0=已归档',
  `create_time` bigint NULL DEFAULT NULL,
  `update_time` bigint NULL DEFAULT NULL,
  `bound_agent_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'ç»‘å®šçš„Agentç±»åž‹',
  `bound_agent_at` timestamp NULL DEFAULT NULL COMMENT 'Agentç»‘å®šæ—¶é—´',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_type`(`plan_type` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_learning_plans_schedule`(`user_id` ASC, `plan_status` ASC, `schedule_enabled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of learning_plans_v3
-- ----------------------------

-- ----------------------------
-- Table structure for learning_sessions_v3
-- ----------------------------
DROP TABLE IF EXISTS `learning_sessions_v3`;
CREATE TABLE `learning_sessions_v3`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `plan_id` bigint NULL DEFAULT NULL COMMENT '关联计划',
  `session_date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '日期 YYYY-MM-DD',
  `started_at` bigint NULL DEFAULT NULL COMMENT '会话开始时间戳',
  `ended_at` bigint NULL DEFAULT NULL COMMENT '会话结束时间戳',
  `total_duration_ms` bigint NULL DEFAULT 0 COMMENT '总学习时长ms',
  `tasks_snapshot` json NULL COMMENT '当日任务完成快照 §11.1',
  `skill_changes` json NULL COMMENT '技能变化 [{name,before,after}]',
  `match_score_before` decimal(5, 2) NULL DEFAULT NULL,
  `match_score_after` decimal(5, 2) NULL DEFAULT NULL,
  `status` tinyint NOT NULL DEFAULT 1,
  `create_time` bigint NULL DEFAULT NULL,
  `update_time` bigint NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_date`(`user_id` ASC, `session_date` ASC) USING BTREE,
  INDEX `idx_date`(`session_date` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of learning_sessions_v3
-- ----------------------------

-- ----------------------------
-- Table structure for learning_tasks_v3
-- ----------------------------
DROP TABLE IF EXISTS `learning_tasks_v3`;
CREATE TABLE `learning_tasks_v3`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `plan_id` bigint NOT NULL COMMENT '关联 learning_plans_v3',
  `skill_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '技能名称',
  `task_type` enum('main','side') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'main' COMMENT '主线/支线',
  `task_status` enum('pending','in_progress','lecture_done','practice_done','code_done','exam_done','skipped','done') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '状态机',
  `estimated_min` int NULL DEFAULT NULL COMMENT '预估时长(分钟)',
  `actual_min` int NULL DEFAULT NULL COMMENT '实际时长(分钟)',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序（支持拖拽 §9.3）',
  `priority` tinyint NOT NULL DEFAULT 5 COMMENT '优先级1-10，10最高（用户可标记紧急）',
  `plan_date` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '安排在哪天 YYYY-MM-DD',
  `start_time` bigint NULL DEFAULT NULL COMMENT '用户点击开始时间',
  `complete_time` bigint NULL DEFAULT NULL COMMENT '完成时间',
  `is_active` tinyint NOT NULL DEFAULT 1 COMMENT '1=有效 0=删除',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1=正常 0=删除',
  `create_time` bigint NULL DEFAULT NULL,
  `update_time` bigint NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_date`(`user_id` ASC, `plan_date` ASC) USING BTREE,
  INDEX `idx_plan`(`plan_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 60 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of learning_tasks_v3
-- ----------------------------

