-- ----------------------------
-- Table structure for students_v3
-- ----------------------------
DROP TABLE IF EXISTS `students_v3`;
CREATE TABLE `students_v3`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '关联 users_v3',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `student_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '学号',
  `school` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '学校',
  `major` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '专业',
  `grade` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '年级/毕业年份',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系方式',
  `email` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系方式',
  `target_job_id` bigint NULL DEFAULT NULL COMMENT '目标岗位 FK',
  `interests` json NULL COMMENT '兴趣方向 [\"AI\",\"前端\"]',
  `skills` json NULL COMMENT '技能列表 [{name,level,source}] - 快速访问冗余',
  `projects` json NULL COMMENT '项目经历 - 快速访问冗余',
  `github_username` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'GitHub 用户名',
  `work_experience` json NULL COMMENT '实习/工作经历',
  `awards` json NULL COMMENT '获奖/证书',
  `self_intro` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '自我评价/个人简介',
  `daily_hours` decimal(3, 1) NULL DEFAULT NULL COMMENT '每日可投入学习时长(h)',
  `target_deadline` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '目标达成时间',
  `onboarding_completed` tinyint NOT NULL DEFAULT 0 COMMENT '0=未完成 1=已完成',
  `status` tinyint NOT NULL DEFAULT 1,
  `create_time` bigint NULL DEFAULT NULL,
  `update_time` bigint NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_target_job`(`target_job_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

