-- ----------------------------
-- Table structure for user_skills_v3
-- ----------------------------
DROP TABLE IF EXISTS `user_skills_v3`;
CREATE TABLE `user_skills_v3`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `skill_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '技能名称',
  `mastery_pct` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '掌握百分比 0-100 §6.2',
  `trust_weight` decimal(3, 2) NOT NULL DEFAULT 0.30 COMMENT '信任权重 §6.1',
  `source` enum('self_report','conversation','github','exam') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'self_report' COMMENT '技能来源 §6.1',
  `last_activity` bigint NULL DEFAULT NULL COMMENT '最后一次使用/学习时间戳',
  `decay_start` bigint NULL DEFAULT NULL COMMENT '开始衰减时间（考试通过3个月后）',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1=有效 0=归档',
  `create_time` bigint NULL DEFAULT NULL,
  `update_time` bigint NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_skill`(`user_id` ASC, `skill_name` ASC) USING BTREE,
  INDEX `idx_skill`(`skill_name` ASC) USING BTREE,
  INDEX `idx_mastery`(`mastery_pct` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 78 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user_skills_v3
-- ----------------------------

-- ----------------------------
-- Table structure for users_v3
-- ----------------------------
DROP TABLE IF EXISTS `users_v3`;
CREATE TABLE `users_v3`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '登录名',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'bcrypt hash',
  `real_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '真实姓名',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `email` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `avatar` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `role` enum('admin','student') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'student',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '1=正常 0=禁用',
  `create_time` bigint NULL DEFAULT NULL COMMENT '创建时间戳ms',
  `update_time` bigint NULL DEFAULT NULL COMMENT '更新时间戳ms',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_username`(`username` ASC) USING BTREE,
  INDEX `idx_role`(`role` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

