INSERT INTO `agent_tasks_v3` VALUES (143, 29, 'assess', '学习评估', '', NULL, 'success', 100, '{\"level\": \"需努力\", \"branch\": {\"id\": \"1\", \"status\": 1, \"userId\": \"29\", \"mergedAt\": null, \"branchName\": \"main\", \"branchType\": \"main\", \"createTime\": \"1784442842982\", \"updateTime\": 1784455861141, \"baseCommitId\": \"1\", \"headCommitId\": \"3\", \"sourceBranchId\": null}, \"commit\": {\"id\": \"3\", \"status\": 1, \"userId\": \"29\", \"message\": \"assessment: TypeScript\", \"branchId\": \"1\", \"deltaJson\": {\"radarChanges\": [{\"after\": 52.88, \"delta\": 52.88, \"before\": 0, \"dimension\": \"前端基础\"}, {\"after\": 27.88, \"delta\": 27.88, \"before\": 0, \"dimension\": \"前端框架\"}, {\"after\": 42, \"delta\": 42, \"before\": 0, \"dimension\": \"工程化\"}, {\"after\": 27, \"delta\": 27, \"before\": 0, \"dimension\": \"后端基础\"}], \"skillChanges\": [{\"name\": \"HTML/CSS\", \"after\": 76.5, \"delta\": 76.5, \"before\": 0}, {\"name\": \"Git\", \"after\": 72, \"delta\": 72, \"before\": 0}, {\"name\": \"JavaScript\", \"after\": 63.75, \"delta\": 63.75, \"before\": 0}, {\"name\": \"SQL\", \"after\": 56, \"delta\": 56, \"before\": 0}, {\"name\": \"TypeScript\", \"after\": 42, \"delta\": 42, \"before\": 0}, {\"name\": \"React\", \"after\": 35.75, \"delta\": 35.75, \"before\": 0}, {\"name\": \"算法基础\", \"after\": 27.5, \"delta\": 27.5, \"before\": 0}, {\"name\": \"Node.js\", \"after\": 27, \"delta\": 27, \"before\": 0}, {\"name\": \"Vue\", \"after\": 20, \"delta\": 20, \"before\": 0}, {\"name\": \"Docker\", \"after\": 12, \"delta\": 12, \"before\": 0}, {\"name\": \"Linux\", \"after\": 8.75, \"delta\": 8.75, \"before\": 0}, {\"name\": \"Python\", \"after\": 6, \"delta\": 6, \"before\": 0}], \"metricsChange\": {\"depthScore\": 77, \"matchScore\": 46.1, \"breadthScore\": 67, \"overallScore\": 29}}, \"skillName\": \"TypeScript\", \"commitType\": \"manual\", \"createTime\": 1784455860997, \"snapshotId\": \"4\", \"updateTime\": 1784455861111, \"payloadJson\": {\"goal\": \"