INSERT INTO `evaluation_evidence_v3` VALUES (1, 1, 1784443130421, 1784443130421, 29, 1, 'conversation', 'agent_assess', '2', 'JavaScript', '目前学习尚未启动，JavaScript知识掌握、实践、效率、习惯和目标达成均处于零分状态。首要任务是立即开始阅读讲义并提交测验，通过制定可执行的微计划打破僵局，逐步建立学习习惯和技术基础。', '{\"goal\": \"掌握 JavaScript\", \"learningData\": \"技能: JavaScript, 已读: false, 测验分数: 未完成\", \"currentProgress\": \"讲义未读, 测验未提交\"}');
INSERT INTO `evaluation_evidence_v3` VALUES (1, 2, 1784455861165, 1784455861165, 29, 2, 'conversation', 'agent_assess', '3', 'TypeScript', '当前学习状态完全停滞，讲义未读、测验未做，各维度得分触底。但危机亦是转机，只要立即启动最小行动（打开讲义第一节），就能打破零循环。建议强化输入与输出的结合，并辅以计时监督，迅速扭转现状。', '{\"goal\": \"掌握 TypeScript\", \"learningData\": \"技能: TypeScript, 已读: false, 测验分数: 未完成\", \"currentProgress\": \"讲义未读, 测验未提交\"}');
INSERT INTO `evaluation_evidence_v3` VALUES (1, 3, 1784456931749, 1784456931749, 29, 3, 'conversation', 'agent_assess', '4', 'React', '评估显示你尚未开始React学习，所有评估维度均为零。这并不意味着能力不足，只是尚未启动。建议立即从阅读讲义和动手编码开始，逐步建立学习习惯，通过测验验证并持续改进。坚持下去，你完全有能力掌握React。', '{\"goal\": \"掌握 React\", \"learningData\": \"技能: React, 已读: false, 测验分数: 未完成\", \"currentProgress\": \"讲义未读, 测验未提交\"}');
INSERT INTO `evaluation_impacts_v3` VALUES (1, 1, 1784443130510, 1784443130510, 29, 1, 1, 2, 2, 1, '[]', '[]', '{\"depthScore\": 0, \"matchScore\": 9, \"breadthScore\": 0, \"overallScore\": 0}', 9.00, '[{\"type\": \"improvement\", \"label\": \"制定逐步学习计划：今日内阅读讲义前3页并完成对应思考题。\", \"priority\": \"high\", \"skillName\": \"学习启动与规划\"}, {\"type\": \"improvement\", \"label\": \"按照讲义顺序学习，边读边在在线编辑器中运行示例代码。\", \"priority\": \"high\", \"skillName\": \"知识输入\"}, {\"type\": \"improvement\", \"label\": \"每完成一个知识小节后，立即完成配套测验或自编小练习。\", \"priority\": \"medium\", \"skillName\": \"练习与测验\"}]');
INSERT INTO `evaluation_impacts_v3` VALUES (1, 2, 1784455861274, 1784455861274, 29, 2, 18, 3, 4, 1, '[{\"name\": \"HTML/CSS\", \"after\": 76.5, \"delta\": 76.5, \"before\": 0}, {\"name\": \"Git\", \"after\": 72, \"delta\": 72, \"before\": 0}, {\"name\": \"JavaScript\", \"after\": 63.75, \"delta\": 63.75, \"before\": 0}, {\"name\": \"SQL\", \"after\": 56, \"delta\": 56, \"before\": 0}, {\"name\": \"TypeScript\", \"after\": 42, \"delta\": 42, \"before\": 0}, {\"name\": \"React\", \"after\": 35.75, \"delta\": 35.75, \"before\": 0}, {\"name\": \"算法基础\", \"after\": 27.5, \"delta\": 27.5, \"before\": 0}, {\"name\": \"Node.js\", \"after\": 27, \"delta\": 27, \"before\": 0}, {\"name\": \"Vue\", \"after\": 20, \"delta\": 20, \"before\": 0}, {\"name\": \"Docker\", \"after\": 12, \"delta\": 12, \"before\": 0}, {\"name\": \"Linux\", \"after\": 8.75, \"delta\": 8.75, \"before\": 0}, {\"name\": \"Python\", \"after\": 6, \"delta\": 6, \"before\": 0}]', '[{\"after\": 52.88, \"delta\": 52.88, \"before\": 0, \"dimension\": \"前端基础\"}, {\"after\": 27.88, \"delta\": 27.88, \"before\": 0, \"dimension\": \"前端框架\"}, {\"after\": 42, \"delta\": 42, \"before\": 0, \"dimension\": \"工程化\"}, {\"after\": 27, \"delta\": 27, \"before\": 0, \"dimension\": \"后端基础\"}]', '{\"depthScore\": 77, \"matchScore\": 46.1, \"breadthScore\": 67, \"overallScore\": 29}', 46.10, '[{\"type\": \"improvement\", \"label\": \"立即开始阅读TypeScript讲义第一章，并设定每日最低学习时长（如45分钟）。\", \"priority\": \"high\", \"skillName\": \"启动学习计划\"}, {\"type\": \"improvement\", \"label\": \"学完每章后当天完成对应测验，并记录错题，每周复盘。\", \"priority\": \"high\", \"skillName\": \"测验与反馈\"}, {\"type\": \"improvement\", \"label\": \"使用TypeScript重写至少两个之前用JavaScript实现的功能模块。\", \"priority\": \"medium\", \"skillName\": \"动手编码\"}]');
INSERT INTO `evaluation_impacts_v3` VALUES (1, 3, 1784456931839, 1784456931839, 29, 3, 19, 4, 5, 1, '[]', '[]', '{\"depthScore\": 0, \"matchScore\": 0, \"breadthScore\": 0, \"overallScore\": 0}', 0.00, '[{\"type\": \"improvement\", \"label\": \"今天内完成讲义第1章的阅读（预计15分钟），并记录阅读笔记。\", \"priority\": \"high\", \"skillName\": \"启动学习\"}, {\"type\": \"improvement\", \"label\": \"明天内搭建React开发环境（create-react-app），并运行第一个Hello World组件。\", \"priority\": \"high\", \"skillName\": \"动手实践\"}, {\"type\": \"improvement\", \"label\": \"完成第一章测验并在三天内提交，分析错题，针对性补充阅读。\", \"priority\": \"medium\", \"skillName\": \"测验反馈\"}]');
