INSERT INTO `evaluation_results_v3` VALUES (1, 18, 1784455861165, 1784455861165, 29, 2, 'TypeScript', 'llm', 'AssessAgentService', 10.00, 100.00, 10.00, '需努力', 0, 0.62, '当前学习状态完全停滞，讲义未读、测验未做，各维度得分触底。但危机亦是转机，只要立即启动最小行动（打开讲义第一节），就能打破零循环。建议强化输入与输出的结合，并辅以计时监督，迅速扭转现状。', '{\"weakPoints\": [{\"level\": \"low\", \"skill\": \"TypeScript基础语法\", \"suggestion\": \"立即从官方文档或讲义第一章开始，每天保证30分钟集中阅读并做笔记。\", \"description\": \"对类型注解、接口、枚举等一窍不通，原因在于讲义未读。\"}, {\"level\": \"low\", \"skill\": \"TS工具类型与泛型\", \"suggestion\": \"在完成基础后，配合实际代码练习，理解Partial、Pick等原理，并尝试改写项目中的函数。\", \"description\": \"未接触Utility Types、泛型约束等进阶内容，无法编写通用组件。\"}, {\"level\": \"low\", \"skill\": \"工程化配置能力\", \"suggestion\": \"在学完核心语法后，搭建一个简单的Node/前端TS项目，逐项配置编译选项。\", \"description\": \"对tsconfig.json、编译选项、声明文件等毫无经验，影响项目落地。\"}], \"improvements\": [{\"area\": \"启动学习计划\", \"action\": \"立即开始阅读TypeScript讲义第一章，并设定每日最低学习时长（如45分钟）。\", \"priority\": \"high\", \"expectedEffect\": \"打破零进度僵局，一周内建立基础概念框架。\"}, {\"area\": \"测验与反馈\", \"action\": \"学完每章后当天完成对应测验，并记录错题，每周复盘。\", \"priority\": \"high\", \"expectedEffect\": \"检验理解程度，及时纠正误解，知识留存率提升至60%以上。\"}, {\"area\": \"动手编码\", \"action\": \"使用TypeScript重写至少两个之前用JavaScript实现的功能模块。\", \"priority\": \"medium\", \"expectedEffect\": \"将理论转化为实践能力，熟悉类型推导、错误排查等实操技能。\"}, {\"area\": \"代码审查\", \"action\": \"寻找有经验的TypeScript开发者进行代码审查，或参与开源项目阅读TS代码。\", \"priority\": \"low\", \"expectedEffect\": \"吸收最佳实践，提升代码质量和风格一致性。\"}], \"encouragement\": \"别让恐惧吞噬行动，哪怕每天只读一页讲义也是前进。TypeScript这扇门，推开了就是新世界。\", \"planAdjustment\": \"原计划目标为掌握TypeScript，但当前进度严重滞后，建议将大目标拆分为两周小目标：第一周完成基础类型与函数，通过测验；第二周攻克泛型与模块。每天固定晚8-9点学习，并在日历标记，用番茄钟计时。\"}', '{\"level\": \"需努力\", \"summary\": \"当前学习状态完全停滞，讲义未读、测验未做，各维度得分触底。但危机亦是转机，只要立即启动最小行动（打开讲义第一节），就能打破零循环。建议强化输入与输出的结合，并辅以计时监督，迅速扭转现状。\", \"dimensions\": [{\"score\": 5, \"trend\": \"down\", \"detail\": \"尚未阅读TypeScript讲义，对类型系统、接口、泛型等核心概念缺乏基本了解。\", \"maxScore\": 100, \"dimension\": \"知识掌握\"}, {\"score\": 0, \"trend\": \"stable\", \"detail\": \"未提交任何测验，无编码记录，无法评估动手解决问题的能力。\", \"maxScore\": 100, \"dimension\": \"实践能力\"}, {\"score\": 0, \"trend\": \"down\", \"detail\": \"当前学习投入为零，单位时间产出无法计算，效率处于冰点。\", \"maxScore\": 100, \"dimension\": \"学习效率\"}, {\"score\": 5, \"trend\": \"down\", \"detail\": \"未见学习规律性，无打卡记录，持续性极差，尚未形成学习节奏。\", \"maxScore\": 100, \"dimension\": \"学习习惯\"}, {\"score\": 5, \"trend\": \"stable\", \"detail\": \"距离“掌握TypeScript”的目标差距极大，路径尚未开始，达成度几乎为零。\", \"maxScore\": 100, \"dimension\": \"目标达成\"}], \"weakPoints\": [{\"level\": \"low\", \"skill\": \"TypeScript基础语法\", \"suggestion\": \"立即从官方文档或讲义第一章开始，每天保证30分钟集中阅读并做笔记。\", \"description\": \"对类型注解、接口、枚举等一窍不通，原因在于讲义未读。\"}, {\"level\": \"low\", \"skill\": \"TS工具类型与泛型\", \"suggestion\": \"在完成基础后，配合实际代码练习，理解Partial、Pick等原理，并尝试改写项目中的函数。\", \"description\": \"未接触Utility Types、泛型约束等进阶内容，无法编写通用组件。\"}, {\"level\": \"low\", \"skill\": \"工程化配置能力\", \"suggestion\": \"在学完核心语法后，搭建一个简单的Node/前端TS项目，逐项配置编译选项。\", \"description\": \"对tsconfig.json、编译选项、声明文件等毫无经验，影响项目落地。\"}], \"improvements\": [{\"area\": \"启动学习计划\", \"action\": \"立即开始阅读TypeScript讲义第一章，并设定每日最低学习时长（如45分钟）。\", \"priority\": \"high\", \"expectedEffect\": \"打破零进度僵局，一周内建立基础概念框架。\"}, {\"area\": \"测验与反馈\", \"action\": \"学完每章后当天完成对应测验，并记录错题，每周复盘。\", \"priority\": \"high\", \"expectedEffect\": \"检验理解程度，及时纠正误解，知识留存率提升至60%以上。\"}, {\"area\": \"动手编码\", \"action\": \"使用TypeScript重写至少两个之前用JavaScript实现的功能模块。\", \"priority\": \"medium\", \"expectedEffect\": \"将理论转化为实践能力，熟悉类型推导、错误排查等实操技能。\"}, {\"area\": \"代码审查\", \"action\": \"寻找有经验的TypeScript开发者进行代码审查，或参与开源项目阅读TS代码。\", \"priority\": \"low\", \"expectedEffect\": \"吸收最佳实践，提升代码质量和风格一致性。\"}], \"overallScore\": 10, \"encouragement\": \"别让恐惧吞噬行动，哪怕每天只读一页讲义也是前进。TypeScript这扇门，推开了就是新世界。\", \"planAdjustment\": \"原计划目标为掌握TypeScript，但当前进度严重滞后，建议将大目标拆分为两周小目标：第一周完成基础类型与函数，通过测验；第二周攻克泛型与模块。每天固定晚8-9点学习，并在日历标记，用番茄钟计时。\"}', 'ai_learning_assessment_v1', '1.0.0');
INSERT INTO `evaluation_results_v3` VALUES (1, 19, 1784456931749, 1784456931749, 29, 3, 'React', 'llm', 'AssessAgentService', 5.00, 100.00, 5.00, '需努力', 0, 0.62, '评估显示你尚未开始React学习，所有评估维度均为零。这并不意味着能力不足，只是尚未启动。建议立即从阅读讲义和动手编码开始，逐步建立学习习惯，通过测验验证并持续改进。坚持下去，你完全有能力掌握React。', '{\"weakPoints\": [{\"level\": \"low\", \"skill\": \"React基础\", \"suggestion\": \"立即开始阅读官方讲义第一部分，理解React的核心理念。\", \"description\": \"完全不了解React概念、JSX、组件等核心知识。\"}, {\"level\": \"low\", \"skill\": \"编程实践\", \"suggestion\": \"在阅读讲义时同步搭建开发环境，边学边练，完成讲义中的示例。\", \"description\": \"没有动手写过任何React代码，缺乏环境搭建和开发能力。\"}, {\"level\": \"low\", \"skill\": \"学习规划\", \"suggestion\": \"制定每日30分钟学习计划，固定时间段，使用番茄钟法保持专注。\", \"description\": \"没有明确的学习计划和时间安排，导致启动困难。\"}, {\"level\": \"low\", \"skill\": \"评估检测\", \"suggestion\": \"完成每个模块后立即完成对应测验，将测验作为知识巩固的手段。\", \"description\": \"未提交测验，无法验证学习效果和查漏补缺。\"}], \"improvements\": [{\"area\": \"启动学习\", \"action\": \"今天内完成讲义第1章的阅读（预计15分钟），并记录阅读笔记。\", \"priority\": \"high\", \"expectedEffect\": \"打破零进度状态，建立学习起点，降低心理启动阻力。\"}, {\"area\": \"动手实践\", \"action\": \"明天内搭建React开发环境（create-react-app），并运行第一个Hello World组件。\", \"priority\": \"high\", \"expectedEffect\": \"将理论知识转化为可见的代码结果，增强学习信心和兴趣。\"}, {\"area\": \"测验反馈\", \"action\": \"完成第一章测验并在三天内提交，分析错题，针对性补充阅读。\", \"priority\": \"medium\", \"expectedEffect\": \"及时检验学习效果，发现知识盲区，调整后续学习重点。\"}, {\"area\": \"习惯养成\", \"action\": \"连续7天，每天在同一时间学习React 30分钟，使用打卡工具记录。\", \"priority\": \"medium\", \"expectedEffect\": \"形成稳定的学习规律，提升学习持续性和效率。\"}], \"encouragement\": \"学习任何新技术，最难的就是迈出第一步。现在你已经意识到目标，行动起来就是最好的开始，加油！\", \"planAdjustment\": \"当前计划已严重滞后，建议重启学习：第一周集中完成基础概念和环境搭建，第二周进入组件化开发与状态管理，每周至少完成2个测验，并记录学习日志。若时间紧张，优先保证每天30分钟的高质量学习，周末进行集中编码实践。\"}', '{\"level\": \"需努力\", \"summary\": \"评估显示你尚未开始React学习，所有评估维度均为零。这并不意味着能力不足，只是尚未启动。建议立即从阅读讲义和动手编码开始，逐步建立学习习惯，通过测验验证并持续改进。坚持下去，你完全有能力掌握React。\", \"dimensions\": [{\"score\": 0, \"trend\": \"stable\", \"detail\": \"尚未阅读讲义，无任何知识输入，处于完全空白状态。\", \"maxScore\": 100, \"dimension\": \"知识掌握\"}, {\"score\": 0, \"trend\": \"stable\", \"detail\": \"未进行任何编码练习，动手能力无法体现。\", \"maxScore\": 100, \"dimension\": \"实践能力\"}, {\"score\": 0, \"trend\": \"stable\", \"detail\": \"没有学习时间投入，单位时间产出为零。\", \"maxScore\": 100, \"dimension\": \"学习效率\"}, {\"score\": 0, \"trend\": \"stable\", \"detail\": \"未建立学习规律，无持续性学习记录。\", \"maxScore\": 100, \"dimension\": \"学习习惯\"}, {\"score\": 0, \"trend\": \"stable\", \"detail\": \"学习目标为掌握React，当前进度为0%，完全未启动。\", \"maxScore\": 100, \"dimension\": \"目标达成\"}], \"weakPoints\": [{\"level\": \"low\", \"skill\": \"React基础\", \"suggestion\": \"立即开始阅读官方讲义第一部分，理解React的核心理念。\", \"description\": \"完全不了解React概念、JSX、组件等核心知识。\"}, {\"level\": \"low\", \"skill\": \"编程实践\", \"suggestion\": \"在阅读讲义时同步搭建开发环境，边学边练，完成讲义中的示例。\", \"description\": \"没有动手写过任何React代码，缺乏环境搭建和开发能力。\"}, {\"level\": \"low\", \"skill\": \"学习规划\", \"suggestion\": \"制定每日30分钟学习计划，固定时间段，使用番茄钟法保持专注。\", \"description\": \"没有明确的学习计划和时间安排，导致启动困难。\"}, {\"level\": \"low\", \"skill\": \"评估检测\", \"suggestion\": \"完成每个模块后立即完成对应测验，将测验作为知识巩固的手段。\", \"description\": \"未提交测验，无法验证学习效果和查漏补缺。\"}], \"improvements\": [{\"area\": \"启动学习\", \"action\": \"今天内完成讲义第1章的阅读（预计15分钟），并记录阅读笔记。\", \"priority\": \"high\", \"expectedEffect\": \"打破零进度状态，建立学习起点，降低心理启动阻力。\"}, {\"area\": \"动手实践\", \"action\": \"明天内搭建React开发环境（create-react-app），并运行第一个Hello World组件。\", \"priority\": \"high\", \"expectedEffect\": \"将理论知识转化为可见的代码结果，增强学习信心和兴趣。\"}, {\"area\": \"测验反馈\", \"action\": \"完成第一章测验并在三天内提交，分析错题，针对性补充阅读。\", \"priority\": \"medium\", \"expectedEffect\": \"及时检验学习效果，发现知识盲区，调整后续学习重点。\"}, {\"area\": \"习惯养成\", \"action\": \"连续7天，每天在同一时间学习React 30分钟，使用打卡工具记录。\", \"priority\": \"medium\", \"expectedEffect\": \"形成稳定的学习规律，提升学习持续性和效率。\"}], \"overallScore\": 5, \"encouragement\": \"学习任何新技术，最难的就是迈出第一步。现在你已经意识到目标，行动起来就是最好的开始，加油！\", \"planAdjustment\": \"当前计划已严重滞后，建议重启学习：第一周集中完成基础概念和环境搭建，第二周进入组件化开发与状态管理，每周至少完成2个测验，并记录学习日志。若时间紧张，优先保证每天30分钟的高质量学习，周末进行集中编码实践。\"}', 'ai_learning_assessment_v1', '1.0.0');
INSERT INTO `evaluation_rubrics_v3` VALUES (1, 1, 1784443130426, 1784443130426, 'ai_learning_assessment_v1', 'AI learning assessment rubric', '1.0.0', 'learning_action', 70, NULL, NULL);
INSERT INTO `exam_questions_v3` VALUES (1, 1, 'JavaScript', NULL, 'choice', '关于 let 和 var 的区别，以下说法正确的是？', '{\"options\": [\"let 有块级作用域，var 没有\", \"let 和 var 完全相同\", \"let 不能重复声明，var 可以\", \"let 会提升，var 不会\"]}', '{\"correct\": 0, \"explanation\": \"let 有块级作用域且不能重复声明，var 是函数作用域且可以重复声明\"}', 1, 0.95, NULL, 1, 'agent', NULL, 1781163995000, 1781163995000);
INSERT INTO `exam_questions_v3` VALUES (2, 1, 'JavaScript', NULL, 'choice', '以下哪个方法会改变原数组？', '{\"options\": [\"map()\", \"filter()\", \"sort()\", \"slice()\"]}', '{\"correct\": 2, \"explanation\": \"sort() 会改变原数组，map/filter/slice 返回新数组\"}', 2, 0.90, NULL, 1, 'agent', NULL, 1781163995000, 1781163995000);
INSERT INTO `exam_questions_v3` VALUES (3, 1, 'JavaScript', NULL, 'coding', '实现一个防抖函数 debounce(fn, delay)', '{\"template\": \"function debounce(fn, delay) {\\n  // 你的代码\\n}\", \"testCases\": [{\"input\": \"连续调用3次间隔100ms delay=300ms\", \"expected\": \"只执行最后一次\"}]}', '{\"solution\": \"function debounce(fn, delay) { let timer; return function(...args) { clearTimeout(timer); timer = setTimeout(() => fn.apply(this, args), delay); }; }\"}', 3, 0.85, NULL, 1, 'agent', NULL, 1781163995000, 1781163995000);
INSERT INTO `exam_questions_v3` VALUES (4, 1, 'React', NULL, 'choice', 'React Hooks 中 useEffect 第二个参数为空数组意味着什么？', '{\"options\": [\"每次渲染都执行\", \"只在组件挂载时执行一次\", \"不执行\", \"只在卸载时执行\"]}', '{\"correct\": 1, \"explanation\": \"空数组表示没有依赖项，只在 mount 时执行一次\"}', 2, 0.92, NULL, 1, 'agent', NULL, 1781163995000, 1781163995000);
INSERT INTO `exam_questions_v3` VALUES (5, 1, 'React', NULL, 'choice', '以下哪个不是 React Hooks 的规则？', '{\"options\": [\"只能在函数组件顶层调用\", \"不能在循环条件中调用\", \"只能在自定义Hook中调用\", \"不能在普通JS函数中调用\"]}', '{\"correct\": 2, \"explanation\": \"Hooks 可以在函数组件和自定义 Hook 中调用，不限于自定义 Hook\"}', 2, 0.88, NULL, 1, 'agent', NULL, 1781163995000, 1781163995000);
INSERT INTO `exam_questions_v3` VALUES (6, 1, 'CSS', NULL, 'choice', 'CSS Grid 中 grid-template-columns: 1fr 2fr 1fr 表示什么？', '{\"options\": [\"三列等宽\", \"第一列和第三列等宽 第二列是它们的两倍\", \"第二列最小\", \"三列自适应\"]}', '{\"correct\": 1, \"explanation\": \"fr 单位按比例分配 1:2:1 表示中间列是两侧的两倍\"}', 1, 0.93, NULL, 1, 'agent', NULL, 1781163995000, 1781163995000);
INSERT INTO `exam_questions_v3` VALUES (7, 1, 'Python', NULL, 'choice', 'Python 中列表推导式 [x**2 for x in range(5)] 的结果是？', '{\"options\": [\"[0,1,4,9,16]\", \"[1,4,9,16,25]\", \"[0,2,4,6,8]\", \"Error\"]}', '{\"correct\": 0, \"explanation\": \"range(5) 是 0-4，平方后为 [0,1,4,9,16]\"}', 1, 0.97, NULL, 1, 'agent', NULL, 1781163995000, 1781163995000);
INSERT INTO `exam_questions_v3` VALUES (8, 2, NULL, NULL, 'choice', '字节跳动前端面试：解释事件循环 Event Loop 机制', '{\"options\": [\"调用栈->微任务队列->宏任务队列\", \"调用栈->宏任务队列->微任务队列\", \"微任务->调用栈->宏任务\", \"宏任务->微任务->调用栈\"]}', '{\"correct\": 0, \"explanation\": \"先执行调用栈，清空后执行微任务队列，再取一个宏任务执行\"}', 3, 0.80, NULL, 0, 'manual', NULL, 1781163995000, 1781163995000);
