INSERT INTO `news_v3` VALUES (7, 'typescript - 百度百科', 'TypeScript是微软于2012年10月发布的开源编程语言，它是JavaScript的一个超集，本质上添加了可选的静态类型和基于类的面向对象编程。TypeScript通过编译器转译为JavaScript代码，可运行在任何浏览器和操作系统。该语言支持为已存在的JavaScript库添加类型信息，并扩展了许多ECMAScript新特性。TypeScript', 'typescript - 百度百科', NULL, 'industry', '[]', 'searxng', 'https://baike.baidu.com/item/typescript/4314718', 1, 1781599497476, 1781599497476, 1781599497476);
