INSERT INTO `news_v3` VALUES (21, '自动智能系统 - 百度百科', '自动智能系统，常称为人工智能（AI），是计算机科学的一个分支，指基于机器（包括软硬件）构建、能够感知环境、自主决策并执行行动以影响物理或虚拟环境的智能系统。其核心在于具备自主性、适应性与学习能力，能通过推断自动获取和应用知识，完成推理、规划、问题求解等复杂任务。机器学习与自然语言处理是其关键技术支撑。...', '自动智能系统 - 百度百科', NULL, 'industry', '[]', 'searxng', 'https://baike.baidu.com/item/%E8%87%AA%E5%8A%A8%E6%99%BA%E8%83%BD%E7%B3%BB%E7%BB%9F/8937303', 1, 1781603396606, 1781603396606, 1781603396606);
