INSERT INTO `news_v3` VALUES (39, '人工智能大模型 - 百度百科', '人工智能大模型（简称“大模型”）是指由人工神经网络构建的一类具有大量参数的人工智能模型。人工智能大模型是近十年来兴起的新兴概念。其通常先通过自监督学习或半监督学习在海量数据上进行预训练，然后通过指令微调和人类对齐等方法进一步优化其性能和能力。大模型具有参数量大、训练数据大、计算资源大等特点，拥有解决通用任务、遵循人类指令、进行复杂推理', '...', NULL, 'industry', '[\"React\", \"前端\"]', 'searxng', 'https://baike.baidu.com/item/%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD%E5%A4%A7%E6%A8%A1%E5%9E%8B/63800799', 1, 1781611773262, 1781611773262, 1781611773262);
