INSERT INTO `news_v3` VALUES (110, 'CNCF x Alibaba 云原生技术公开课 - 阿里云开发者社区', '《CNCF x Alibaba 云原生技术公开课》由阿里云和CNCF联合开发,课程全程免费,将为您带来:完善的知识体系,打造属于自己的云原生技能树;理解云原生技术背后的思想与本质;与知识体系相辅相成的动手实践;一线技术团队云原生技术最佳实践', '...', NULL, 'industry', '[\"React\", \"前端\"]', 'searxng', 'https://edu.aliyun.com/roadmap/cloudnative', 1, 1782216576168, 1782216576168, 1782216576168);
INSERT INTO `news_v3` VALUES (111, '到底什么是“云原生”?-云栖号-阿里云', '到底什么是“云原生”?-阿里云官方内容分发平台。一手云资讯,企业上云案例库,最佳上云实践,云产品在线课程,助力您轻松上云!-作为云计算领域的一个新兴概念,云原生现在频繁出现在我们的视野中,很多互联网大咖把它奉为至宝,走到哪说到哪。', '...', NULL, 'industry', '[\"React\", \"前端\"]', 'searxng', 'https://yqh.aliyun.com/detail/17342', 1, 1782216579746, 1782216579746, 1782216579746);
INSERT INTO `news_v3` VALUES (112, '什么是 Kubernetes? | Microsoft Azure', '为了使 Kubernetes 更易于为组织所采用,也更便于开发者使用,Microsoft 在短短三年内将参与开放源代码项目...', '...', NULL, 'industry', '[\"React\", \"前端\"]', 'searxng', 'https://azure.microsoft.com/zh-cn/topic/kubernetes/', 1, 1782216594528, 1782216594528, 1782216594528);
