INSERT INTO `resumes_v3` VALUES (9, 29, 2, 1, 'v1-Web前端实习生', 0, '{\"awards\": [], \"skills\": [{\"name\": \"HTML/CSS\", \"source\": \"github\", \"masteryPct\": 85}, {\"name\": \"Git\", \"source\": \"github\", \"masteryPct\": 80}, {\"name\": \"JavaScript\", \"source\": \"github\", \"masteryPct\": 75}, {\"name\": \"SQL\", \"source\": \"exam\", \"masteryPct\": 70}, {\"name\": \"TypeScript\", \"source\": \"exam\", \"masteryPct\": 60}, {\"name\": \"React\", \"source\": \"github\", \"masteryPct\": 55}, {\"name\": \"算法基础\", \"source\": \"exam\", \"masteryPct\": 50}, {\"name\": \"Node.js\", \"source\": \"exam\", \"masteryPct\": 45}, {\"name\": \"Vue\", \"source\": \"exam\", \"masteryPct\": 40}, {\"name\": \"Docker\", \"source\": \"exam\", \"masteryPct\": 30}, {\"name\": \"Linux\", \"source\": \"exam\", \"masteryPct\": 25}, {\"name\": \"Python\", \"source\": \"self_report\", \"masteryPct\": 20}], \"projects\": [], \"targetJob\": {\"title\": \"Web前端实习生\", \"company\": \"腾讯\", \"location\": \"深圳\", \"requiredSkills\": [{\"name\": \"JavaScript\"}, {\"name\": \"HTML/CSS\"}, {\"name\": \"React\"}], \"preferredSkills\": [{\"name\": \"微信小程序\"}]}, \"personalInfo\": {\"name\": \"张演示\", \"email\": \"\", \"grade\": \"大四\", \"major\": \"软件工程\", \"phone\": \"\", \"github\": \"\", \"school\": \"北京大学\", \"selfIntro\": \"全栈开发学习者，2 年前端经验，正在往后端和 DevOps 方向拓展\", \"studentNo\": \"\"}, \"workExperience\": []}', '<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>张演示 - 简历</title>\n    <style>\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        body {\n            font-size: 13px;\n            line-height: 1.5;\n            color: #222;\n            background: #e8e8e8;\n            font-family: \"PingFang SC\", \"Microsoft YaHei\", \"Helvetica Neue\", Arial, sans-serif;\n            -webkit-font-smoothing: antialiased;\n            padding: 20px 0;\n        }\n\n        .resume {\n            max-width: 190mm;\n            width: 190mm;\n            margin: 0 auto;\n            background: #fff;\n            padding: 12mm 14mm 10mm 14mm;\n            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);\n            border-radius: 2px;\n        }\n\n        /* ========== 头部 ========== */\n        .resume-header {\n            margin-bottom: 18px;\n            padding-bottom: 14px;\n            border-bottom: 2px solid #1a1a2e;\n            display: flex;\n            justify-content: space-between;\n            align-items: flex-end;\n            flex-wrap: wrap;\n        }\n\n        .resume-header .name-title h1 {\n            font-size: 28px;\n            font-weight: 700;\n            color: #1a1a2e;\n            letter-spacing: 2px;\n            line-height: 1.2;\n        }\n\n        .resume-header .name-title .subtitle {\n            font-size: 13px;\n            color: #555;\n            margin-top: 2px;\n            letter-spacing: 0.5px;\n        }\n\n        .resume-header .header-contact {\n            font-size: 12px;\n            color: #666;\n            text-align: right;\n            line-height: 1.6;\n            padding-bottom: 2px;\n        }\n\n        .resume-header .header-contact span {\n            display: inline-block;\n        }\n\n        .resume-header .header-contact .sep {\n            margin: 0 6px;\n            color: #ccc;\n        }\n\n        /* ========== 通用区块 ========== */\n        .resume-section {\n            margin-bottom: 16px;\n            page-break-inside: avoid;\n        }\n\n        .resume-section h2 {\n            font-size: 16px;\n            font-weight: 600;\n            color: #1a1a2e;\n            padding-bottom: 5px;\n            margin-bottom: 10px;\n            border-bottom: 1.5px solid #d0d0d0;\n            letter-spacing: 0.5px;\n            page-break-after: avoid;\n        }\n\n        .resume-section h2 .highlight {\n            color: #2563eb;\n        }\n\n        .resume-section .section-body {\n            padding-left: 2px;\n        }\n\n        /* ========== 求职意向 ========== */\n        .job-target {\n            font-size: 15px;\n            font-weight: 600;\n            color: #1a1a2e;\n            margin-bottom: 4px;\n        }\n\n        .job-target .company {\n            color: #2563eb;\n        }\n\n        .job-requirements {\n            font-size: 12.5px;\n            color: #555;\n            display: flex;\n            align-items: center;\n            flex-wrap: wrap;\n            gap: 4px 0;\n        }\n\n        .job-requirements .req-label {\n            color: #888;\n            margin-right: 4px;\n        }\n\n        .job-requirements .req-tag {\n            display: inline-block;\n            background: #eef2ff;\n            color: #2563eb;\n            font-weight: 500;\n            padding: 1px 10px;\n            border-radius: 3px;\n            font-size: 12px;\n            margin: 0 2px;\n        }\n\n        /* ========== 个人信息 ========== */\n        .contact-line {\n            display: flex;\n            flex-wrap: wrap;\n            align-items: center;\n            gap: 6px 18px;\n            font-size: 12.5px;\n            color: #444;\n            margin-bottom: 8px;\n            padding: 6px 10px;\n            background: #f9f9fb;\n            border-radius: 4px;\n        }\n\n        .contact-line .contact-item {\n            display: inline-flex;\n            align-items: center;\n            gap: 4px;\n        }\n\n        .contact-line .contact-item .label {\n            color: #888;\n            font-weight: 500;\n        }\n\n        .contact-line .contact-item .value {\n            color: #222;\n        }\n\n        .contact-line .contact-item .value.na {\n            color: #aaa;\n            font-style: italic;\n        }\n\n        .self-evaluation {\n            font-size: 13px;\n            color: #333;\n            padding: 6px 10px;\n            background: #f9f9fb;\n            border-radius: 4px;\n            border-left: 3px solid #2563eb;\n        }\n\n        .self-evaluation .eval-label {\n            font-weight: 600;\n            color: #1a1a2e;\n            margin-right: 4px;\n        }\n\n        /* ========== 技能清单 ========== */\n        .skills-list {\n            display: flex;\n            flex-wrap: wrap;\n            gap: 7px 8px;\n            padding: 2px 0;\n        }\n\n        .skill-tag {\n            display: inline-flex;\n            align-items: center;\n            gap: 4px;\n            background: #f0f0f4;\n            padding: 4px 12px 4px 12px;\n            border-radius: 4px;\n            font-size: 12px;\n            color: #222;\n            border: 1px solid #e6e6ea;\n            transition: background 0.1s;\n        }\n\n        .skill-tag .skill-name {\n            font-weight: 500;\n        }\n\n        .skill-tag .skill-percent {\n            font-weight: 600;\n            color: #2563eb;\n            font-size: 11px;\n        }\n\n        .skill-tag .skill-source {\n            font-size: 9.5px;\n            color: #999;\n            margin-left: 2px;\n            font-weight: 400;\n            letter-spacing: 0.2px;\n            background: rgba(0, 0, 0, 0.04);\n            padding: 0 5px;\n            border-radius: 2px;\n            line-height: 1.4;\n        }\n\n        /* ========== 来源颜色标记 ========== */\n        .skill-tag .skill-source.source-github {\n            color: #2563eb;\n            background: rgba(37, 99, 235, 0.08);\n        }\n\n        .skill-tag .skill-source.source-cert {\n            color: #059669;\n            background: rgba(5, 150, 105, 0.08);\n        }\n\n        .skill-tag .skill-source.source-self {\n            color: #a0a0a0;\n            background: rgba(160, 160, 160, 0.08);\n        }\n\n        /* ========== 打印优化 ========== */\n        @media print {\n            body {\n                background: #fff;\n                padding: 0;\n                -webkit-print-color-adjust: exact;\n                print-color\n</html>', NULL, 0, NULL, 1784448572096, 1784451135205);
INSERT INTO `resumes_v3` VALUES (10, 29, 1, 1, 'v1-前端开发工程师', 0, '{\"awards\": [], \"skills\": [{\"name\": \"HTML/CSS\", \"source\": \"github\", \"masteryPct\": 85}, {\"name\": \"Git\", \"source\": \"github\", \"masteryPct\": 80}, {\"name\": \"JavaScript\", \"source\": \"github\", \"masteryPct\": 75}, {\"name\": \"SQL\", \"source\": \"exam\", \"masteryPct\": 70}, {\"name\": \"TypeScript\", \"source\": \"exam\", \"masteryPct\": 60}, {\"name\": \"React\", \"source\": \"github\", \"masteryPct\": 55}, {\"name\": \"算法基础\", \"source\": \"exam\", \"masteryPct\": 50}, {\"name\": \"Node.js\", \"source\": \"exam\", \"masteryPct\": 45}, {\"name\": \"Vue\", \"source\": \"exam\", \"masteryPct\": 40}, {\"name\": \"Docker\", \"source\": \"exam\", \"masteryPct\": 30}, {\"name\": \"Linux\", \"source\": \"exam\", \"masteryPct\": 25}, {\"name\": \"Python\", \"source\": \"self_report\", \"masteryPct\": 20}], \"projects\": [], \"targetJob\": {\"title\": \"前端开发工程师\", \"company\": \"字节跳动\", \"location\": \"北京\", \"requiredSkills\": [{\"name\": \"JavaScript\"}, {\"name\": \"React\"}, {\"name\": \"TypeScript\"}, {\"name\": \"CSS\"}], \"preferredSkills\": [{\"name\": \"Vue\"}, {\"name\": \"Node.js\"}]}, \"personalInfo\": {\"name\": \"张演示\", \"email\": \"\", \"grade\": \"大四\", \"major\": \"软件工程\", \"phone\": \"\", \"github\": \"\", \"school\": \"北京大学\", \"selfIntro\": \"全栈开发学习者，2 年前端经验，正在往后端和 DevOps 方向拓展\", \"studentNo\": \"\"}, \"workExperience\": []}', '<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>\n@page { size: A4; margin: 14mm 15mm; }\n* { margin:0; padding:0; box-sizing:border-box; }\nbody { width:min(210mm,100%); min-height:297mm; margin:0 auto; padding:clamp(18px,6vw,14mm) clamp(16px,6vw,15mm); background:#fff; color:#252523; font:13px/1.55 \'Inter\',\'PingFang SC\',\'Microsoft YaHei\',sans-serif; }\nh1 { color:#141413; font-size:27px; font-weight:650; line-height:1.15; }\nh2 { margin:15px 0 8px; padding-bottom:5px; border-bottom:1px solid #cc785c; color:#141413; font-size:14px; font-weight:650; page-break-after:avoid; }\n.header { display:flex; align-items:flex-end; justify-content:space-between; gap:24px; padding-bottom:11px; border-bottom:2px solid #141413; }\n.headline { color:#6c6a64; margin-top:5px; }\n.contact { max-width:72mm; color:#6c6a64; font-size:11px; text-align:right; }\n.contact span+span:before { content:\' · \'; color:#cc785c; }\n.summary { margin-top:11px; color:#3d3d3a; }\n.tags { display:flex; flex-wrap:wrap; gap:6px; }\n.tag { display:inline-flex; align-items:center; gap:5px; padding:3px 8px; border:1px solid #e6dfd8; border-radius:4px; background:#faf9f5; color:#3d3d3a; font-size:11px; }\n.tag.matched { border-color:#cc785c; color:#a9583e; }\n.tag small { color:#8e8b82; }\n.tag.award { background:#f5f0e8; }\n.entry { margin-bottom:10px; page-break-inside:avoid; }\n.entry-head { display:flex; justify-content:space-between; gap:16px; color:#141413; }\n.entry-head span,.meta { color:#6c6a64; font-size:11px; }\nul { margin:4px 0 0 17px; } li { padding-left:2px; margin:2px 0; }\n.intent { color:#a9583e; font-weight:600; }\n@media (max-width:480px) { .header,.entry-head { align-items:flex-start; flex-direction:column; gap:4px; } .contact { text-align:left; } }\n@media screen { html { background:#e9e7e2; } body { box-shadow:0 2px 16px rgba(20,20,19,.12); } }\n@media print { body { width:auto; min-height:auto; margin:0; padding:0; -webkit-print-color-adjust:exact; print-color-adjust:exact; } }\n</style></head>\n<body>\n<div class=\"header\">\n  <div><h1>张演示</h1><div class=\"headline\">北京大学 · 软件工程 · 大四</div></div>\n  \n</div>\n<div class=\"summary intent\">求职方向：前端开发工程师 · 字节跳动 · 北京</div>\n<div class=\"summary\">北京大学软件工程大四学生，2年前端开发经验，熟练JavaScript/TypeScript、React及CSS，正拓展Vue、Node.js与DevOps技能。</div>\n<h2>专业技能</h2><div class=\"tags\"><span class=\"tag matched\">JavaScript<small>75%</small></span><span class=\"tag matched\">TypeScript<small>60%</small></span><span class=\"tag matched\">React<small>55%</small></span><span class=\"tag\">HTML/CSS<small>85%</small></span><span class=\"tag\">Git<small>80%</small></span><span class=\"tag\">SQL<small>70%</small></span><span class=\"tag\">算法基础<small>50%</small></span><span class=\"tag\">Node.js<small>45%</small></span><span class=\"tag\">Vue<small>40%</small></span><span class=\"tag\">Docker<small>30%</small></span><span class=\"tag\">Linux<small>25%</small></span><span class=\"tag\">Python<small>20%</small></span></div>\n\n\n\n</body></html>', NULL, 0, NULL, 1784451143180, 1784453166223);
INSERT INTO `resumes_v3` VALUES (11, 29, 1, 1, 'v1-前端开发工程师', 0, '{\"awards\": [], \"skills\": [{\"name\": \"HTML/CSS\", \"source\": \"github\", \"masteryPct\": 85}, {\"name\": \"Git\", \"source\": \"github\", \"masteryPct\": 80}, {\"name\": \"JavaScript\", \"source\": \"github\", \"masteryPct\": 75}, {\"name\": \"SQL\", \"source\": \"exam\", \"masteryPct\": 70}, {\"name\": \"TypeScript\", \"source\": \"exam\", \"masteryPct\": 60}, {\"name\": \"React\", \"source\": \"github\", \"masteryPct\": 55}, {\"name\": \"算法基础\", \"source\": \"exam\", \"masteryPct\": 50}, {\"name\": \"Node.js\", \"source\": \"exam\", \"masteryPct\": 45}, {\"name\": \"Vue\", \"source\": \"exam\", \"masteryPct\": 40}, {\"name\": \"Docker\", \"source\": \"exam\", \"masteryPct\": 30}, {\"name\": \"Linux\", \"source\": \"exam\", \"masteryPct\": 25}, {\"name\": \"Python\", \"source\": \"self_report\", \"masteryPct\": 20}], \"projects\": [], \"targetJob\": {\"title\": \"前端开发工程师\", \"company\": \"字节跳动\", \"location\": \"北京\", \"requiredSkills\": [{\"name\": \"JavaScript\"}, {\"name\": \"React\"}, {\"name\": \"TypeScript\"}, {\"name\": \"CSS\"}], \"preferredSkills\": [{\"name\": \"Vue\"}, {\"name\": \"Node.js\"}]}, \"personalInfo\": {\"name\": \"张演示\", \"birth\": \"\", \"email\": \"\", \"grade\": \"大四\", \"major\": \"软件工程\", \"phone\": \"\", \"github\": \"\", \"school\": \"北京大学\", \"hometown\": \"\", \"selfIntro\": \"全栈开发学习者，2 年前端经验，正在往后端和 DevOps 方向拓展\", \"studentNo\": \"\"}, \"workExperience\": [], \"campusExperience\": []}', '<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>张演示 - 个人简历</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root {\n    --primary: #cc785c;\n    --primary-active: #a9583e;\n    --primary-disabled: #e6dfd8;\n    --ink: #141413;\n    --body-color: #3d3d3a;\n    --body-strong: #252523;\n    --muted: #6c6a64;\n    --muted-soft: #8e8b82;\n    --hairline: #e6dfd8;\n    --hairline-soft: #ebe6df;\n    --canvas: #faf9f5;\n    --surface-soft: #f5f0e8;\n    --surface-card: #efe9de;\n    --surface-cream-strong: #e8e0d2;\n    --surface-dark: #8a7f78;\n    --surface-dark-elevated: #9a8f88;\n    --surface-dark-soft: #7a6f68;\n    --on-primary: #ffffff;\n    --on-dark: #2f2925;\n    --on-dark-soft: #3d3835;\n    --accent-teal: #5db8a6;\n    --font-display: \"Cormorant Garamond\", \"Tiempos Headline\", Garamond, \"Times New Roman\", serif;\n    --font-body: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Noto Sans SC\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n  }\n  *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }\n  @page { size: A4; margin: 0; }\n  body {\n    font-family: var(--font-body);\n    font-size: 14px;\n    line-height: 1.55;\n    color: var(--body-color);\n    background: #e8e0d2;\n    -webkit-font-smoothing: antialiased;\n  }\n  .page {\n    width: 210mm;\n    min-height: 297mm;\n    margin: 20px auto;\n    background: var(--canvas);\n    box-shadow: 0 1px 3px rgba(20,20,19,0.08);\n    position: relative;\n  }\n  @media print {\n    * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; color-adjust: exact !important; }\n    html, body { background: white !important; margin: 0; padding: 0; font-size: 13px; }\n    .page { margin: 0 !important; box-shadow: none !important; width: 100% !important; min-height: auto !important; background: var(--canvas) !important; }\n    .no-print { display: none !important; }\n    .header { padding: 24px 36px 20px; gap: 20px; background: var(--surface-dark) !important; }\n    .photo-area { width: 90px; height: 112px; background: var(--surface-dark-elevated) !important; }\n    .name { font-size: 28px; margin-bottom: 4px; }\n    .job-intent { font-size: 13px; margin-bottom: 10px; color: var(--primary) !important; }\n    .contact-row { font-size: 12px; gap: 4px 14px; }\n    .content { padding: 18px 36px 24px; }\n    .section { margin-bottom: 14px; }\n    .section-title { font-size: 17px; padding-bottom: 5px; margin-bottom: 8px; }\n    .edu-school { font-size: 14px; }\n    .edu-major, .edu-courses { font-size: 12px; }\n    .project { padding: 10px 14px; margin-bottom: 10px; background: var(--surface-card) !important; break-inside: avoid; }\n    .project-name { font-size: 14px; }\n    .project-desc, .project-details li { font-size: 12px; }\n    .project-result { font-size: 11px; }\n    .project-role { font-size: 9px; background: var(--primary) !important; }\n    .tag { font-size: 10px; padding: 1px 7px; background: var(--canvas) !important; }\n    .skill-grid { gap: 8px; break-inside: avoid; }\n    .skill-card { padding: 10px 12px; background: var(--surface-card) !important; }\n    .skill-card-title { font-size: 12px; margin-bottom: 4px; }\n    .skill-card-body { font-size: 11px; line-height: 1.5; }\n    .campus-item { padding: 8px 12px; margin-bottom: 8px; background: var(--surface-card) !important; break-inside: avoid; }\n    .campus-title { font-size: 13px; }\n    .campus-desc { font-size: 12px; }\n    .eval-list li { font-size: 12px; margin-bottom: 3px; }\n    .section-title .marker { background: var(--primary) !important; }\n    .eval-list li::before { color: var(--primary) !important; }\n    .project-result { color: var(--primary) !important; }\n    .project-section { page-break-before: always; }\n    .drag-hint { display: none !important; }\n    .drag-handle { display: none !important; }\n    [contenteditable=\"true\"]:hover, [contenteditable=\"true\"]:focus { background: transparent !important; box-shadow: none !important; }\n  }\n  .header {\n    background: var(--surface-dark);\n    color: var(--on-dark);\n    padding: 36px 44px 32px;\n    display: flex;\n    align-items: center;\n    gap: 28px;\n  }\n  .photo-area {\n    flex-shrink: 0;\n    width: 108px;\n    height: 136px;\n    border: 2px dashed var(--on-dark-soft);\n    border-radius: 12px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n    transition: border-color 0.2s;\n    overflow: hidden;\n    background: var(--surface-dark-elevated);\n  }\n  .photo-area:hover { border-color: var(--primary); }\n  .photo-area .icon { font-size: 26px; margin-bottom: 6px; opacity: 0.4; }\n  .photo-area .hint { font-size: 11px; opacity: 0.35; text-align: center; line-height: 1.3; }\n  .photo-area img { width: 100%; height: 100%; object-fit: cover; display: none; }\n  .photo-area.has-photo img { display: block; }\n  .photo-area.has-photo .icon, .photo-area.has-photo .hint { display: none; }\n  .header-info { flex: 1; }\n  .name {\n    font-family: var(--font-display);\n    font-size: 36px;\n    font-weight: 400;\n    letter-spacing: -0.5px;\n    line-height: 1.1;\n    margin-bottom: 6px;\n    color: var(--on-dark);\n  }\n  .job-intent {\n    font-size: 14px;\n    color: var(--primary);\n    margin-bottom: 16px;\n  }\n  .contact-row {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 5px 18px;\n    font-size: 13px;\n    color: var(--on-dark-soft);\n  }\n  .contact-item { display: flex; align-items: center; gap: 6px; }\n  .contact-item .label {\n    color: #5a5450;\n    font-size: 11px;\n    text-transform: uppercase;\n    letter-spacing: 1px;\n    font-weight: 500;\n  }\n  .content { padding: 28px 44px 36px; }\n  .section { margin-bottom: 22px; }\n  .section:last-child { margin-bottom: 0; }\n  .section-title {\n    font-family: var(--font-display);\n    font-size: 20px;\n    font-weight: 500;\n    color: var(--ink);\n    letter-spacing: -0.3px;\n    padding-bottom: 8px;\n    border-bottom: 1.5px solid var(--hairline);\n    margin-bottom: 14px;\n    display: flex;\n    align-items: center;\n    gap: 10px;\n  }\n  .section-title .marker {\n    width: 8px;\n    height: 8px;\n    background: var(--primary);\n    border-radius: 2px;\n    flex-shrink: 0;\n  }\n  .edu-row { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 5px; }\n  .edu-school { font-size: 15px; font-weight: 600; color: var(--ink); }\n  .edu-major { font-size: 13px; color: var(--muted); margin-left: 8px; }\n  .edu-courses { font-size: 13px; color: var(--muted); line-height: 1.7; }\n  .project-list { position: relative; }\n  .project {\n    margin-bottom: 16px;\n    background: var(--surface-card);\n    border-radius: 12px;\n    padding: 16px 20px;\n    position: relative;\n    transition: box-shadow 0.2s;\n    break-inside: avoid;\n    page-break-inside: avoid;\n  }\n  .project:last-child { margin-bottom: 0; }\n  .project:hover { box-shadow: 0 2px 12px rgba(20,20,19,0.06); }\n  .project-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: baseline;\n    margin-bottom: 4px;\n  }\n  .project-name { font-size: 15px; font-weight: 600; color: var(--ink); }\n  .project-role {\n    font-size: 10px;\n    color: var(--on-primary);\n    background: var(--primary);\n    padding: 2px 10px;\n    border-radius: 9999px;\n    font-weight: 500;\n    flex-shrink: 0;\n    letter-spacing: 0.5px;\n    text-transform: uppercase;\n  }\n  .tech-tags {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 4px;\n    margin-bottom: 8px;\n    align-items: center;\n  }\n  .tag {\n    font-size: 11px;\n    padding: 2px 9px;\n    background: var(--canvas);\n    color: var(--muted);\n    border-radius: 9999px;\n    font-weight: 500;\n    border: 1px solid var(--hairline-soft);\n  }\n  .project-desc { font-size: 13px; color: var(--body-strong); margin-bottom: 8px; line-height: 1.6; }\n  .project-details { list-style: none; padding: 0; }\n  .project-details li {\n    font-size: 13px;\n    line-height: 1.65;\n    color: var(--body-color);\n    padding-left: 14px;\n    position: relative;\n    margin-bottom: 3px;\n  }\n  .project-details li::before {\n    content: \"\";\n    position: absolute;\n    left: 0;\n    top: 8px;\n    width: 5px;\n    height: 5px;\n    border-radius: 1px;\n    background: var(--hairline);\n  }\n  .project-result { font-size: 12px; color: var(--primary); font-weight: 500; margin-top: 8px; padding-left: 10px; }\n  .campus-item {\n    margin-bottom: 12px;\n    padding: 12px 16px;\n    background: var(--surface-card);\n    border-radius: 12px;\n    break-inside: avoid;\n  }\n  .campus-item:last-child { margin-bottom: 0; }\n  .campus-header {\n    display: flex;\n    justify-content: space-between;\n    align-items: baseline;\n    margin-bottom: 4px;\n  }\n  .campus-title { font-size: 14px; font-weight: 600; color: var(--ink); }\n  .campus-desc { font-size: 13px; color: var(--body-color); line-height: 1.65; }\n  .skill-grid {\n    display: grid;\n    grid-template-columns: 1fr 1fr 1fr;\n    gap: 10px;\n    break-inside: avoid;\n    page-break-inside: avoid;\n  }\n  .skill-card { background: var(--surface-card); border-radius: 12px; padding: 14px 16px; position: relative; transition: box-shadow 0.2s; }\n  .skill-card:hover { box-shadow: 0 2px 12px rgba(20,20,19,0.06); }\n  .skill-card-title {\n    font-size: 13px;\n    font-weight: 600;\n    color: var(--ink);\n    margin-bottom: 6px;\n    display: flex;\n    align-items: center;\n    gap: 6px;\n  }\n  .skill-card-title::before {\n    content: \"\";\n    width: 6px;\n    height: 6px;\n    background: var(--primary);\n    border-radius: 2px;\n    flex-shrink: 0;\n  }\n  .skill-card-body { font-size: 12px; color: var(--body-color); line-height: 1.7; }\n  .eval-list { list-style: none; padding: 0; }\n  .eval-list li {\n    font-size: 13px;\n    line-height: 1.7;\n    color: var(--body-color);\n    padding-left: 18px;\n    position: relative;\n    margin-bottom: 5px;\n  }\n  .eval-list li::before {\n    content: \"✦\";\n    position: absolute;\n    left: 0;\n    top: 0;\n    color: var(--primary);\n    font-size: 10px;\n  }\n  [contenteditable=\"true\"] {\n    outline: none;\n    border-radius: 4px;\n    transition: background 0.2s, box-shadow 0.2s;\n  }\n  [contenteditable=\"true\"]:hover { background: rgba(204,120,92,0.04); }\n  [contenteditable=\"true\"]:focus { background: rgba(204,120,92,0.06); box-shadow: 0 0 0 2px rgba(204,120,92,0.15); }\n  .toolbar {\n    position: fixed;\n    bottom: 24px;\n    left: 50%;\n    transform: translateX(-50%);\n    background: var(--surface-dark);\n    color: var(--on-dark);\n    padding: 10px 24px;\n    border-radius: 12px;\n    display: flex;\n    align-items: center;\n    gap: 16px;\n    font-size: 13px;\n    box-shadow: 0 4px 24px rgba(20,20,19,0.15);\n    z-index: 100;\n  }\n  .toolbar button {\n    background: var(--primary);\n    color: var(--on-primary);\n    border: none;\n    padding: 8px 20px;\n    border-radius: 8px;\n    font-size: 13px;\n    font-weight: 500;\n    font-family: var(--font-body);\n    cursor: pointer;\n    transition: background 0.15s, transform 0.1s;\n  }\n  .toolbar button:hover { background: var(--primary-active); }\n  .toolbar button:active { transform: scale(0.95); }\n  .toolbar .sep { width: 1px; height: 18px; background: var(--surface-dark-elevated); }\n  .toolbar .tip { font-size: 12px; color: var(--on-dark-soft); }\n  .drag-hint {\n    font-size: 11px;\n    color: var(--muted-soft);\n    text-align: right;\n    margin-bottom: 6px;\n    font-style: italic;\n  }\n  @media screen and (max-width: 800px) {\n    .page { width: 100%; margin: 0; }\n    .header { padding: 24px; gap: 18px; flex-wrap: wrap; }\n    .content { padding: 20px 24px 28px; }\n    .name { font-size: 28px; }\n    .skill-grid { grid-template-columns: 1fr; }\n    .project { padding: 14px 16px; }\n    .toolbar { bottom: 12px; padding: 8px 16px; gap: 10px; }\n  }\n</style>\n</head>\n<body>\n<div class=\"page\">\n  <div class=\"header\">\n    <div class=\"photo-area\" id=\"photoArea\" onclick=\"document.getElementById(\'photoInput\').click()\">\n      <div class=\"icon\">📷</div>\n      <div class=\"hint\">点击上传<br>证件照</div>\n      <img id=\"photoPreview\" alt=\"证件照\">\n      <input type=\"file\" id=\"photoInput\" accept=\"image/*\" style=\"display:none\">\n    </div>\n    <div class=\"header-info\">\n      <div class=\"name\" contenteditable=\"true\">张演示</div>\n      <div class=\"job-intent\" contenteditable=\"true\">前端开发工程师</div>\n      <div class=\"summary\" contenteditable=\"true\" style=\"font-size:12px;color:var(--muted);margin-top:-10px;margin-bottom:16px;line-height:1.6\">软件工程专业，2年前端开发经验，掌握HTML/CSS、JavaScript、TypeScript与React，了解Node.js和Vue，正拓展后端与DevOps能力。</div>\n      <div class=\"contact-row\">\n\n      </div>\n    </div>\n  </div>\n  <div class=\"content\">\n    <!-- 教育背景 -->\n    <div class=\"section\">\n      <div class=\"section-title\"><span class=\"marker\"></span>教育背景</div>\n      <div class=\"edu-row\">\n        <div>\n          <span class=\"edu-school\" contenteditable=\"true\">北京大学</span>\n          <span class=\"edu-major\" contenteditable=\"true\">| 软件工程 大四</span>\n        </div>\n      </div>\n    </div>\n    <!-- 校园经历 -->\n\n    <!-- 专业技能 -->\n    <div class=\"section\">\n      <div class=\"section-title\"><span class=\"marker\"></span>专业技能</div>\n      <div class=\"drag-hint\">⇔ 拖拽技能卡片可调整顺序</div>\n      <div class=\"skill-grid\" id=\"skillGrid\">\n        <div class=\"skill-card\" draggable=\"true\">\n          <div class=\"skill-card-title\" contenteditable=\"true\">前端基础</div>\n          <div class=\"skill-card-body\" contenteditable=\"true\">HTML/CSS、JavaScript</div>\n        </div>\n        <div class=\"skill-card\" draggable=\"true\">\n          <div class=\"skill-card-title\" contenteditable=\"true\">框架与语言</div>\n          <div class=\"skill-card-body\" contenteditable=\"true\">React、TypeScript、Vue</div>\n        </div>\n        <div class=\"skill-card\" draggable=\"true\">\n          <div class=\"skill-card-title\" contenteditable=\"true\">工具与后端</div>\n          <div class=\"skill-card-body\" contenteditable=\"true\">Git、SQL、Node.js、Docker、Linux、Python</div>\n        </div>\n      </div>\n    </div>\n    <!-- 项目经历 -->\n\n    <!-- 自我评价 -->\n    <div class=\"section\">\n      <div class=\"section-title\"><span class=\"marker\"></span>自我评价</div>\n      <ul class=\"eval-list\">\n        <li contenteditable=\"true\">具备扎实的前端基础，持续学习全栈技术，有较强自驱力。</li>\n        <li contenteditable=\"true\">2年开发经验，注重代码质量，能快速适应新技术栈。</li>\n      </ul>\n    </div>\n  </div>\n</div>\n<div class=\"toolbar no-print\">\n  <span class=\"tip\">点击文字编辑 · 拖拽卡片调序 · 导出时请勾选\"背景图形\"</span>\n  <span class=\"sep\"></span>\n  <button onclick=\"window.print()\">导出 PDF</button>\n</div>\n<script>\n  (function() {\n    var photoInput = document.getElementById(\'photoInput\');\n    var photoArea = document.getElementById(\'photoArea\');\n    var photoPreview = document.getElementById(\'photoPreview\');\n    if (photoInput) {\n      photoInput.addEventListener(\'change\', function(e) {\n        var file = e.target.files[0];\n        if (!file) return;\n        var reader = new FileReader();\n        reader.onload = function(ev) { photoPreview.src = ev.target.result; photoArea.classList.add(\'has-photo\'); };\n        reader.readAsDataURL(file);\n      });\n    }\n    // Prevent Enter in single-line fields\n    document.querySelectorAll(\'.name, .job-intent, .edu-school, .edu-major, .project-name, .skill-card-title, .campus-title\')\n      .forEach(function(el) { el.addEventListener(\'keydown\', function(e) { if (e.key === \'Enter\') e.preventDefault(); }); });\n  })();\n</script>\n</body>\n</html>', NULL, 1, NULL, 1784453171306, 1784453171306);
